125	// ── Fetcher ────────────────────────────────────────────────────────────
126	
127	async function fetchAuthPageConfig(): Promise<AuthPageConfig> {
128	  try {
129	    // Use the REST API directly to avoid type-generation dependency.
130	    // The table has public SELECT via RLS so anon key works.
131	    const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
132	    const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
133	    if (!url || !key) return DEFAULTS;
134	
135	    const res = await fetch(
136	      `${url}/rest/v1/auth_page_config?select=*&limit=1`,
137	      {
138	        headers: {
139	          apikey: key,
140	          Authorization: `Bearer ${key}`,
141	          Accept: "application/json",
142	        },
143	      },
144	    );
145	
146	    if (!res.ok) return DEFAULTS;
147	
148	    const rows: AuthPageConfigRow[] = await res.json();
149	    const data = rows[0];
150	    if (!data) return DEFAULTS;
151	
152	    return {
153	      hero_headline: data.hero_headline ?? DEFAULTS.hero_headline,
154	      hero_description: data.hero_description ?? DEFAULTS.hero_description,
155	      logo_url: data.logo_url ?? null,
156	      social_proof_count:
157	        data.social_proof_count ?? DEFAULTS.social_proof_count,
158	      social_proof_label:
159	        data.social_proof_label ?? DEFAULTS.social_proof_label,
160	      testimonials: Array.isArray(data.testimonials_json)
161	        ? data.testimonials_json
162	        : DEFAULTS.testimonials,
163	      trust_badges: Array.isArray(data.trust_badges_json)
164	        ? data.trust_badges_json
165	        : DEFAULTS.trust_badges,
166	      signup_benefits: Array.isArray(data.signup_benefits_json)
167	        ? data.signup_benefits_json
168	        : DEFAULTS.signup_benefits,
169	      signup_headline: data.signup_headline ?? DEFAULTS.signup_headline,
170	      signup_social_proof_count:
171	        data.signup_social_proof_count ?? DEFAULTS.signup_social_proof_count,
172	      signup_social_proof_label:
173	        data.signup_social_proof_label ?? DEFAULTS.signup_social_proof_label,
174	      google_auth_enabled: data.google_auth_enabled ?? true,
175	      microsoft_auth_enabled: data.microsoft_auth_enabled ?? true,
176	      magic_link_enabled: data.magic_link_enabled ?? true,
177	      signin_heading: data.signin_heading ?? DEFAULTS.signin_heading,
178	      signin_subheading: data.signin_subheading ?? DEFAULTS.signin_subheading,
179	      signup_heading: data.signup_heading ?? DEFAULTS.signup_heading,
180	      signup_subheading: data.signup_subheading ?? DEFAULTS.signup_subheading,
181	    };
182	  } catch {
183	    // Table may not exist yet — fall back to defaults
184	    return DEFAULTS;
185	  }
186	}
187	
188	// ── Hook ───────────────────────────────────────────────────────────────
189	
190	export function useAuthPageConfig() {
191	  const { data, isLoading } = useQuery({
192	    queryKey: ["auth-page-config"],
193	    queryFn: fetchAuthPageConfig,
194	    staleTime: 5 * 60 * 1000, // 5 minutes
195	    gcTime: 30 * 60 * 1000, // 30 minutes
196	    retry: 1,
197	  });
198	
199	  return {
200	    config: data ?? DEFAULTS,
201	    isLoading,
202	  };
203	}
