const acceptInvite = useCallback(
  async (token: string) => {
    try {
      const {
        data: { session },
      } = await supabase.auth.getSession();
      if (!session?.access_token) return;

      const res = await fetch(
        `${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/accept-team-invite`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.access_token}`,
            apikey: process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? "",
          },
          body: JSON.stringify({ token }),
        },
      );

      const json = await res.json();
      if (res.ok && json.success) {
        toast.success(`Joined team: ${json.team_name ?? "Team"}`);
        router.replace("/team");
        return;
      }
    } catch {
      // Silently fail — user can accept invite manually later
    }
    router.replace(nextPath);
  },
  [router, nextPath],
);

// ── Redirect authenticated users ──────────────────────────────────
useEffect(() => {
  if (!loading && user) {
    if (inviteToken) {
      acceptInvite(inviteToken);
    } else {
      router.replace(nextPath);
    }
  }
}, [user, loading, router, inviteToken, acceptInvite, nextPath]);

